```ts
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { refreshSession } from "../src/auth/refresh.ts";
import { createSession, getSession, resetSessions, revokeSession } from "../src/auth/session.ts";

beforeEach(() => resetSessions());

test("refreshSession returns undefined for an unknown token", () => {
  assert.equal(refreshSession("unknown"), undefined);
});

test("refreshSession replaces the session for the same user", () => {
  const original = createSession("u_1");
  const refreshed = refreshSession(original.token);

  assert.ok(refreshed);
  assert.equal(refreshed.userId, original.userId);
  assert.notEqual(refreshed.token, original.token);
  assert.equal(getSession(original.token), undefined);
  assert.equal(getSession(refreshed.token), refreshed);
  assert.equal(refreshSession(original.token), undefined);
});

test("refreshSession returns undefined for a revoked session", () => {
  const session = createSession("u_2");
  revokeSession(session.token);

  assert.equal(refreshSession(session.token), undefined);
});
